150	
151	    /**
152	     * Builds the next customer code, formatted {@code <LAST3>-<NNNN>} where LAST3 is the
153	     * upper-cased first three letters of the owner's last name and NNNN is a global 4-digit
154	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
155	     *
156	     * @param lastName the owner's last name
157	     * @return the assigned customer code
158	     */
159	    private String nextCustomerCode(String lastName) {
160	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
161	        int sequence = this.clinicService.findAllOwners().size() + 1;
162	        return String.format("%s-%04d", last3, sequence);
163	    }
164	
165	    /**
166	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
167	     * last two digits of the registrationDate year, zero-padded (e.g. {@code SMI-0007-M26}).
168	     *
169	     * @param customerCode     the owner's assigned customer code
170	     * @param registrationDate the owner's registration date
171	     * @return the assigned membership number
172	     */
173	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
174	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
175	    }
176	
177	    /**
178	     * Counts the existing owners that already share the given firstName and lastName, compared
179	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
180	     * the owners that pre-existed this create.
181	     *
182	     * @param firstName the new owner's first name
183	     * @param lastName  the new owner's last name
184	     * @return the number of existing namesakes
185	     */
186	    private int countNamesakes(String firstName, String lastName) {
187	        return (int) this.clinicService.findAllOwners().stream()
188	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
189	                && equalsIgnoreCase(existing.getLastName(), lastName))
190	            .count();
191	    }
192	
193	    private boolean equalsIgnoreCase(String a, String b) {
194	        return a == null ? b == null : a.equalsIgnoreCase(b);
195	    }
196	
197	    /**
198	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
199	     * offending field so the client learns about all of them at once.
200	     *
201	     * @param ownerFieldsDto the submitted owner fields
202	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
203	     *                                     missing or blank
204	     */
205	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
206	        List<String> errors = new ArrayList<>();
207	        if (isBlank(ownerFieldsDto.getFirstName())) {
208	            errors.add("firstName");
209	        }
210	        if (isBlank(ownerFieldsDto.getLastName())) {
211	            errors.add("lastName");
212	        }
213	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
214	            errors.add("address");
215	        }
216	        if (isBlank(ownerFieldsDto.getCity())) {
217	            errors.add("city");
218	        }
219	        if (isBlank(ownerFieldsDto.getTelephone())) {
220	            errors.add("telephone");
221	        }
222	        if (!errors.isEmpty()) {
223	            throw new MissingOwnerFieldsException(errors);
224	        }
225	    }
226	
227	    private boolean isBlank(String value) {
228	        return value == null || value.isBlank();
229	    }
230	
231	    /**
232	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
233	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
234	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
235	     * followed by 8 to 15 digits.
236	     *
237	     * @param telephone the raw telephone value as submitted
238	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
239	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
240	     */
241	    private String normalizeTelephone(String telephone) {
242	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
243	        String nationalSignificantNumber;
244	        if (cleaned.startsWith("+")) {
245	            nationalSignificantNumber = cleaned.substring(1);
246	        } else {
247	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
248	            nationalSignificantNumber = "61" + national;
249	        }
250	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
251	            throw new InvalidTelephoneException(telephone);
252	        }
253	        return "+" + nationalSignificantNumber;
254	    }
255	
256	    /**
257	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
258	     * value is treated as absent and returns {@code null}); when present the value must be a
259	     * syntactically valid address, and is stored and returned lower-cased.
260	     *
261	     * @param email the raw email value as submitted, may be {@code null}
262	     * @return the lower-cased email, or {@code null} when none was supplied
263	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
264	     */
265	    private String normalizeEmail(String email) {
266	        if (email == null || email.isBlank()) {
267	            return null;
268	        }
269	        String normalized = email.trim().toLowerCase();
270	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
271	            throw new InvalidEmailException(email);
272	        }
273	        return normalized;
274	    }
275	
276	    /**
277	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
278	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
279	     * comparison, so numbers that differ only in formatting still count as duplicates.
280	     *
281	     * @param e164Telephone the E.164 telephone of the owner being created
282	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
283	     */
284	    private void rejectDuplicateTelephone(String e164Telephone) {
285	        boolean inUse = this.clinicService.findAllOwners().stream()
286	            .map(Owner::getTelephone)
287	            .filter(existing -> existing != null)
288	            .map(this::toComparableTelephone)
289	            .filter(existing -> existing != null)
290	            .anyMatch(e164Telephone::equals);
291	        if (inUse) {
292	            throw new DuplicateTelephoneException(e164Telephone);
293	        }
294	    }
295	
296	    /**
297	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
298	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
299	     * than aborting the whole create.
300	     */
301	    private String toComparableTelephone(String telephone) {
302	        try {
303	            return normalizeTelephone(telephone);
304	        } catch (InvalidTelephoneException ex) {
305	            return null;
306	        }
307	    }
308	
309	    /**
310	     * Applies the household rule to an owner being created. An owner belongs to the same household
311	     * as an existing owner when their lastName and address both match (compared case-insensitively
312	     * with runs of whitespace collapsed to a single space).
313	     *
314	     * <p>When no such existing owner exists there is nothing to do. Otherwise the request must
315	     * deliberately opt in to sharing that household by setting {@code sharesHousehold=true}: when it
316	     * does, the new owner and every existing owner in the household are assigned the same stable
317	     * {@link #householdId(String, String) householdId}; when it does not, the create is rejected.
318	     *
319	     * @param owner            the owner being created
320	     * @param sharesHousehold  the request's {@code sharesHousehold} flag, may be {@code null}
321	     * @throws DuplicateHouseholdException if another owner shares the same lastName and address and
322	     *                                     the request did not opt in with {@code sharesHousehold=true}
323	     */
324	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
325	        String lastNameKey = toHouseholdKey(owner.getLastName());
326	        String addressKey = toHouseholdKey(owner.getAddress());
327	        List<Owner> household = this.clinicService.findAllOwners().stream()
328	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
329	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
330	            .toList();
331	        if (household.isEmpty()) {
332	            return;
333	        }
334	        if (!Boolean.TRUE.equals(sharesHousehold)) {
335	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
336	        }
337	        String householdId = householdId(lastNameKey, addressKey);
338	        owner.setHouseholdId(householdId);
339	        for (Owner existing : household) {
340	            if (!householdId.equals(existing.getHouseholdId())) {
341	                existing.setHouseholdId(householdId);
342	                this.clinicService.saveOwner(existing);
343	            }
344	        }
345	    }
346	
347	    /**
348	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
349	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
350	     * lastName and address keys. Being a pure function of the household, every owner in it derives
351	     * the same value regardless of creation order.
352	     *
353	     * @param lastNameKey the normalized household lastName key
354	     * @param addressKey  the normalized household address key
355	     * @return the household identifier
356	     */
357	    private String householdId(String lastNameKey, String addressKey) {
358	        try {
359	            byte[] digest = MessageDigest.getInstance("SHA-256")
360	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
361	            StringBuilder hex = new StringBuilder(digest.length * 2);
362	            for (byte b : digest) {
363	                hex.append(String.format("%02x", b));
364	            }
365	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
366	        } catch (NoSuchAlgorithmException ex) {
367	            throw new IllegalStateException("SHA-256 not available", ex);
368	        }
369	    }
370	
371	    /**
372	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
373	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
374	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
375	     * string.
376	     */
377	    private String toHouseholdKey(String value) {
378	        if (value == null) {
379	            return "";
380	        }
381	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
382	    }
383	
384	    /**
385	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
386	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
387	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
388	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
389	     * value, or one that is blank once trimmed, normalizes to an empty string.
390	     *
391	     * @param address the raw address value as submitted, may be {@code null}
392	     * @return the normalized address, or an empty string when none was supplied
393	     */
394	    private String normalizeAddress(String address) {
395	        if (address == null) {
396	            return "";
397	        }
398	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
399	        if (collapsed.isEmpty()) {
400	            return "";
401	        }
402	        String[] tokens = collapsed.split(" ");
403	        StringBuilder normalized = new StringBuilder(collapsed.length());
404	        for (int i = 0; i < tokens.length; i++) {
405	            if (i > 0) {
406	                normalized.append(' ');
407	            }
408	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
409	        }
410	        return normalized.toString();
411	    }
412	
413	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
414	    @Override
415	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
416	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
417	        if (currentOwner == null) {
418	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
419	        }
420	        currentOwner.setAddress(ownerFieldsDto.getAddress());
421	        currentOwner.setCity(ownerFieldsDto.getCity());
422	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
423	        currentOwner.setLastName(ownerFieldsDto.getLastName());
424	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
425	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
426	        this.clinicService.saveOwner(currentOwner);
427	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
428	    }
429	
430	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
431	    @Transactional
432	    @Override
433	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
434	        Owner owner = this.clinicService.findOwnerById(ownerId);
435	        if (owner == null) {
436	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
437	        }
438	        this.clinicService.deleteOwner(owner);
439	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
440	    }
441	
442	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
443	    @Override
444	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
445	        Owner owner = this.clinicService.findOwnerById(ownerId);
446	        if (owner == null) {
447	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
448	        }
449	        HttpHeaders headers = new HttpHeaders();
450	        Pet pet = petMapper.toPet(petFieldsDto);
451	        owner.setId(ownerId);
452	        pet.setOwner(owner);
453	        pet.getType().setName(null);
454	        this.clinicService.savePet(pet);
455	        PetDto petDto = petMapper.toPetDto(pet);
456	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
457	            .buildAndExpand(pet.getId()).toUri());
458	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
459	    }
460	
461	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
462	    @Override
463	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
464	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
465	        if (currentOwner != null) {
466	            Pet currentPet = this.clinicService.findPetById(petId);
467	            if (currentPet != null) {
468	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
469	                currentPet.setName(petFieldsDto.getName());
470	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
471	                this.clinicService.savePet(currentPet);
472	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
473	            }
474	        }
475	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
476	    }
477	
478	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
479	    @Override
480	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
481	        HttpHeaders headers = new HttpHeaders();
482	        Visit visit = visitMapper.toVisit(visitFieldsDto);
483	        Pet pet = new Pet();
484	        pet.setId(petId);
485	        visit.setPet(pet);
486	        this.clinicService.saveVisit(visit);
487	        VisitDto visitDto = visitMapper.toVisitDto(visit);
488	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
489	            .buildAndExpand(visit.getId()).toUri());
490	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
491	    }
492	
493	
494	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
495	    @Override
496	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
497	        Owner owner = this.clinicService.findOwnerById(ownerId);
498	        if (owner != null) {
499	            Pet pet = owner.getPet(petId);
500	            if (pet != null) {
501	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
502	            }
503	        }
504	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
505	    }
506	}
